using UnityEngine;
using Zombera.World.CityPipeline.WorldBuilder;

public static class LandformProbe
{
    public static string Run()
    {
        var service = Object.FindFirstObjectByType<WorldBuilderService>(FindObjectsInactive.Include);
        if (service == null) return "no service";
        var a = service.Artifacts;
        if (a == null) return "no artifacts";
        var lf = a.Landforms;
        if (lf == null) return "landforms=null";
        return "landforms!=null type=" + lf.GetType().Name
            + " w=" + lf.Width + " h=" + lf.Height
            + " heights=" + (lf.WorldHeights != null ? lf.WorldHeights.Length : -1)
            + " hydro=" + (a.Hydrology != null);
    }
}
